# app.R — Normal dist with mean & ±1 SD (ShinyLive-ready, dynamic height)
library(shiny)
# --- OUP light-theme tokens ---
OUP_BACKGROUND <- "#DFDFDF"
OUP_VALUE_BOX  <- "#CECECE"
OUP_BORDER     <- "#8C8C8C"
OUP_RED        <- "#8A1E00"
OUP_BROWN      <- "#BE5A16"
OUP_ORANGE     <- "#E57726"
OUP_TRACK_GREY <- "#AFAFAF"
OUP_TEXT       <- "#000000"

# Theme CSS (browser fonts; no additional R package dependencies)
oup_css <- paste0("
  :root{
    --oup-bg: ", OUP_BACKGROUND, ";
    --oup-panel: ", OUP_VALUE_BOX, ";
    --oup-border: ", OUP_BORDER, ";
    --oup-accent: ", OUP_BROWN, ";
    --oup-orange: ", OUP_ORANGE, ";
    --oup-track: ", OUP_TRACK_GREY, ";
    --oup-text: ", OUP_TEXT, ";
  }

  html{
    overflow-y: scroll !important;
    overflow-x: hidden !important;
  }

  body{
    position: static !important;
    height: auto !important;
    min-height: 100% !important;
    max-height: none !important;
    overflow: visible !important;
    touch-action: pan-y !important;
    background: var(--oup-bg) !important;
    color: var(--oup-text) !important;
    font-family: 'Lexend', system-ui, -apple-system, Segoe UI, Roboto,
                 'Helvetica Neue', Arial, sans-serif !important;
    font-weight: 350;
  }

  .container-fluid{
    max-width: 1100px;
    overflow: visible !important;
    background: var(--oup-bg) !important;
    color: var(--oup-text) !important;
    padding-top: 16px;
    padding-top: calc(16px + env(safe-area-inset-top));
    padding-bottom: 18px;
    padding-bottom: calc(18px + env(safe-area-inset-bottom));
  }

  .shiny-input-container { margin-bottom: 10px; }

  h1, h2, h3, h4, h5, h6 {
    color: var(--oup-text) !important;
    font-family: 'Lexend', sans-serif !important;
  }

  h2.title {
    font-size: 20px;
    line-height: 1.25;
    margin: 6px 0 10px;
    font-weight: 600;
  }

  .no-stack {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }

  .no-stack .left {
    flex: 0 0 320px;
    min-width: 260px;
  }

  .no-stack .right {
    flex: 1 1 auto;
    min-width: 0;
  }

  .no-stack .left .shiny-input-container .control-label {
    margin-top: 16px;
    color: var(--oup-text) !important;
    font-weight: 600;
  }

  .no-stack .left .shiny-input-container:first-of-type .control-label {
    margin-top: 50px;
  }

  .no-stack .left .sidebar-title {
    margin-top: 16px;
  }

  .legend-dot {
    display: inline-block;
    width: 14px;
    height: 14px;
    border-radius: 7px;
    margin-right: 6px;
    border: 1px solid var(--oup-border);
  }

  .legend-item {
    margin-bottom: 6px;
    color: var(--oup-text);
  }

  .sidebar-title {
    margin-top: 8px;
    font-weight: 600;
    color: var(--oup-text);
  }

  #plotBox {
    background: var(--oup-bg) !important;
    border: 2px solid var(--oup-border) !important;
    padding: 12px 12px 16px;
    border-radius: 10px;
    box-shadow: none;
    margin-bottom: 10px;
  }

  .form-control,
  .form-select,
  .selectize-input,
  input[type='number'] {
    background-color: var(--oup-panel) !important;
    color: var(--oup-text) !important;
    border: 1px solid var(--oup-border) !important;
    box-shadow: none !important;
  }

  .form-control:focus,
  .form-select:focus,
  .selectize-input.focus {
    border-color: var(--oup-accent) !important;
    outline: 0 !important;
    box-shadow: 0 0 0 .15rem rgba(190,90,22,.22) !important;
  }

  .selectize-dropdown,
  .selectize-dropdown .active {
    background: var(--oup-panel) !important;
    color: var(--oup-text) !important;
    border-color: var(--oup-border) !important;
  }

  .irs--shiny .irs-single,
  .irs--shiny .irs-from,
  .irs--shiny .irs-to {
  background: var(--oup-panel) !important;
  color: var(--oup-text) !important;
  border: 1px solid var(--oup-border) !important;

  top: -3px !important;
  }

  .irs--shiny .irs-grid-text {
    font-size: 14px;
  }

  .irs--shiny .irs-line,
  .irs--shiny .irs-bar,
  .irs--shiny .irs-bar-edge {
    height: 6px;
  }

  .irs--shiny .irs-line {
    background: var(--oup-track) !important;
    border-color: var(--oup-border) !important;
  }

  .irs--shiny .irs-bar,
  .irs--shiny .irs-bar-edge {
    background: var(--oup-orange) !important;
    border-color: var(--oup-orange) !important;
  }

  .irs--shiny .irs-slider,
  .irs--shiny .irs-handle,
  .irs--shiny .irs-handle > i:first-child {
    background: var(--oup-panel) !important;
    border-color: var(--oup-border) !important;
  }

  .irs--shiny .irs-single,
  .irs--shiny .irs-from,
  .irs--shiny .irs-to {
    background: var(--oup-panel) !important;
    color: var(--oup-text) !important;
    border: 1px solid var(--oup-border) !important;
  }

  .irs--shiny .irs-min,
  .irs--shiny .irs-max,
  .irs--shiny .irs-grid-text {
    color: var(--oup-text) !important;
  }

  .btn,
  .btn-default,
  .action-button {
    background: var(--oup-panel) !important;
    border: 2px solid #5F5F5F !important;
    color: var(--oup-text) !important;
    font-weight: 500;
    box-shadow: none !important;
  }

  .btn:hover,
  .btn:focus,
  .btn:active,
  .action-button:hover,
  .action-button:focus,
  .action-button:active {
    background: var(--oup-panel) !important;
    border-color: var(--oup-accent) !important;
    color: var(--oup-text) !important;
    box-shadow: 0 0 0 .15rem rgba(190,90,22,.22) !important;
  }

  #distPlot img {
    display: block;
    width: 100%;
    height: auto !important;
  }

  small,
  .shiny-text-output {
    color: var(--oup-text) !important;
  }

  @media (max-width: 576px) {
    .container-fluid {
      padding-top: 20px;
      padding-top: calc(20px + env(safe-area-inset-top));
      padding-left: 12px;
      padding-right: 12px;
    }

    h2.title { font-size: 18px; }

    .no-stack {
      flex-direction: column;
      gap: 12px;
    }

    .no-stack .left,
    .no-stack .right {
      flex: 1 1 100%;
      min-width: 0;
      width: 100%;
    }

    .no-stack .left {
      flex-basis: auto;
    }

    .no-stack .left .shiny-input-container .control-label {
      margin-top: 12px;
    }

    .no-stack .left .shiny-input-container:first-of-type .control-label {
      margin-top: 8px;
    }
  }
")

ui <- fluidPage(
  tags$head(
    tags$style(HTML(oup_css)),
    # Google Fonts (browser loads; no R downloads)
    tags$link(rel = "preconnect", href = "https://fonts.googleapis.com"),
    tags$link(rel = "preconnect", href = "https://fonts.gstatic.com", crossorigin = "anonymous"),
    tags$link(
      href = "https://fonts.googleapis.com/css2?family=Lexend:wght@300;400;500&family=Recursive:wght,MONO@400,1&display=swap",
      rel  = "stylesheet"
    ),
    # iFrame Resizer (safe when embedded)
    tags$script(src = "https://cdn.jsdelivr.net/npm/iframe-resizer/js/iframeResizer.contentWindow.min.js"),
    tags$script(HTML("
      document.addEventListener('shiny:idle', function(){
        if (window.parentIFrame && window.parentIFrame.size) window.parentIFrame.size();
      });
    "))
  ),

  # --- Dynamic-height helpers (same pattern you used before) ---
  tags$head(
    tags$script(HTML("
      (function () {
        function send() {
          if (!window.Shiny) return;
          Shiny.setInputValue('vh_px', window.innerHeight, {priority:'event'});
          Shiny.setInputValue('resizeTick', Date.now(),     {priority:'event'});
        }
        window.addEventListener('load', send, {once:true});
        document.addEventListener('shiny:connected', send);
        window.addEventListener('resize', send);
        window.addEventListener('orientationchange', send);
      })();
    ")),
    tags$script(HTML("
      Shiny.addCustomMessageHandler('setDistHeight', function(px){
        var el = document.getElementById('distPlot');
        if (el) el.style.height = String(px) + 'px';
      });
    "))
  ),

  div(class = "no-stack",
      div(class = "left",
          sliderInput("mean", "Variable mean", min = -5, max = 5, value = 0, step = 1),
          sliderInput("sd",   "Variable standard deviation", min = 0.5, max = 5.0, value = 2.5, step = 0.1),
          div(class = "sidebar-title", "Colour key"),
          div(class = "legend-item", span(class="legend-dot", style=paste0("background:", OUP_ORANGE)),     "Mean"),
          div(class = "legend-item", span(class="legend-dot", style=paste0("background:", OUP_BORDER)), "±1 SD"),
          br(),
          actionButton("reset", "Reset to 0 & 2.5", class = "btn btn-secondary")
      ),
      div(class = "right",
          div(id = "plotBox",
              plotOutput("distPlot"),
              br(),
              tags$small(textOutput("stats"))
          )
      )
  )
)

server <- function(input, output, session) {

  # ---- Dynamic plot height (width-driven + viewport cap) ----
  plotHeight <- reactive({
    w <- session$clientData$output_distPlot_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 360
    compact  <- (w < 520)
    # keep your original aspect logic, just made reactive
    h_from_w <- if (compact) max(240, 0.44 * w) else max(260, min(520, 0.60 * w))
    # cap by viewport height to avoid the moat
    vh <- input$vh_px
    if (is.numeric(vh) && is.finite(vh) && vh > 0) {
      cap <- if (compact) 0.46 * vh else 0.52 * vh
      h_from_w <- min(h_from_w, cap)
    }
    round(h_from_w)
  })

  observeEvent(list(plotHeight(), input$resizeTick), {
    session$sendCustomMessage('setDistHeight', plotHeight())
  }, ignoreInit = FALSE)

  observeEvent(input$reset, {
    updateSliderInput(session, "mean", value = 0)
    updateSliderInput(session, "sd",   value = 2.5)
  })

  output$distPlot <- renderPlot({
    m <- input$mean
    s <- input$sd

    # Safe width for first render + tiny layout flag
    wcd   <- session$clientData$output_distPlot_width
    w_use <- if (is.null(wcd) || !is.finite(wcd) || wcd <= 0) 360 else wcd
    tiny  <- (w_use < 420)

    # Data
    xs <- seq(-15, 15, length.out = 1600)
    ys <- dnorm(xs, mean = m, sd = s)
    yM <- suppressWarnings(max(ys, na.rm = TRUE)); if (!is.finite(yM) || yM <= 0) yM <- 1e-6

    op <- par(no.readonly = TRUE); on.exit(par(op), add = TRUE)
    par(
      fg = OUP_TEXT, col.axis = OUP_TEXT, col.lab = OUP_TEXT, col = OUP_TEXT,
      mar  = if (tiny) c(3.0, 3.2, 1.8, 0.8) else c(4.6, 4.6, 3.0, 1.2),
      mgp  = if (tiny) c(1.9, 0.5, 0)        else c(2.5, 0.8, 0),
      xaxs = if (tiny) "i" else "r",
      yaxs = if (tiny) "i" else "r",
      cex.axis = if (tiny) 0.90 else 1.00,
      cex.lab  = if (tiny) 0.95 else 1.05
    )

    # Axes + curve
    plot(xs, ys, type = "n",
         xlab = "", ylab = "Density",
         xlim = c(-15, 15),
         ylim = c(0, yM * (if (tiny) 1.06 else 1.14)),
         axes = TRUE, frame.plot = TRUE)
    lines(xs, ys, lwd = 2, col = OUP_TEXT)

    # Guides
    abline(v = m,     col = OUP_ORANGE,     lwd = 2)
    abline(v = m - s, col = OUP_BORDER, lwd = 2)
    abline(v = m + s, col = OUP_BORDER, lwd = 2)

    # Labels inside plot region
    usr   <- par("usr")
    y_lab <- usr[4] - (if (tiny) 0.07 else 0.09) * diff(usr[3:4])
    clamp <- function(x, lo = -15, hi = 15) pmin(hi, pmax(lo, x))
    text(clamp(m),     y_lab, "Mean",  col = OUP_ORANGE,     cex = if (tiny) 0.85 else 0.95)
    text(clamp(m - s), y_lab, "-1 SD", col = OUP_BORDER, cex = if (tiny) 0.85 else 0.95)
    text(clamp(m + s), y_lab, "+1 SD", col = OUP_BORDER, cex = if (tiny) 0.85 else 0.95)
  },
  width = function() {
    w <- session$clientData$output_distPlot_width
    if (is.null(w) || !is.finite(w) || w <= 0) w <- 360
    round(max(280, min(1100, w)))
  },
  height = function() plotHeight(),
  res = 96,
  execOnResize = TRUE,
  bg = OUP_BACKGROUND
  )

  output$stats <- renderText({
    sprintf("mean = %.2f   |   sd = %.2f", input$mean, input$sd)
  })
}

shinyApp(ui, server)
